import os, re, json, glob

def load_instances():
    """Load all grid instances from the session log."""
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        print("RLM_SESSION_DIR not set, skipping instance loading")
        return {}

    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    if not os.path.exists(session_file):
        print(f"Session file not found: {session_file}")
        return {}

    with open(session_file, 'r') as f:
        content = f.read()

    grids = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_text = content[m.end():].split('\n')[:h]
        if k not in grids and all(len(r) == w and all(x.isdigit() for x in r) for r in rows_text):
            grids[k] = [[int(x) for x in r] for r in rows_text]

    return grids

d = load_instances()
for k, v in sorted(d.items()):
    print(f"{k}: {len(v)}x{len(v[0])} if square, {len(v[0])}x{len(v)} otherwise")

